[DllImport("user32.dll", SetLastError = true)]
public static extern int SendMessage(
    nint hWnd,
    int Msg,
    nint wParam,
    nint lParam);

[DllImport("user32.dll", SetLastError = true)]
private static extern nint SendMessageTimeout(
    nint hWnd,
    int Msg,
    nint wParam,
    nint lParam,
    uint fuFlags,
    uint uTimeout,
    out nint lpdwResult);

public static bool TrySendMessage(
    nint hWnd,
    int Msg,
    nint wParam,
    nint lParam,
    uint TimeoutMilliseconds) {
    const uint SMTO_BLOCK = 0x0001;
    const uint SMTO_ABORTIFHUNG = 0x0002;
    return SendMessageTimeout(
        hWnd,
        Msg,
        wParam,
        lParam,
        SMTO_BLOCK | SMTO_ABORTIFHUNG,
        TimeoutMilliseconds,
        out _) != 0;
}

if (!CopyData.TrySendMessage(
    hWnd: hwnd,
    Msg: CopyData.WM_COPYDATA,
    wParam: 0x1,
    lParam: cdsPointer,
    TimeoutMilliseconds: 2000)) {
    Log.Write("Timed out while forwarding an argument to the existing application instance.");
}

else if (!CopyData.TrySendMessage(hwnd, CopyData.WM_SHOWFORM, 0, 0, 2000)) {
    Log.Write("Timed out while asking the existing application instance to show itself.");
}
